(function(root){'use strict';const api={payout(entry,coins){return Math.round(entry*Math.min(4,1+Math.max(0,coins)/100)*100)/100},canCashout(entry,coins){return api.payout(entry,coins)>=Math.max(0,Number(entry)||0)*2},settle(round,users,outcome,coins){if(!round||round.status!=='active')return false;const collected=Math.max(0,Number(coins)||0);if(outcome==='cashout'&&!api.canCashout(round.entry,collected))return false;const user=users.find(u=>u.email===round.email);if(!user)return false;round.status=outcome;round.coins=collected;round.payout=outcome==='loss'?0:api.payout(round.entry,collected);user.balance=Math.round((user.balance+round.payout)*100)/100;return true}};if(typeof module==='object')module.exports=api;else root.SubwayRound=api})(typeof window==='object'?window:globalThis);
